changeSet.sql:
DROP TABLE IF EXISTS "user".user_used_document CASCADE;

CREATE TABLE IF NOT EXISTS "user".user_package_usage (
    id              UUID PRIMARY KEY DEFAULT uuid_generate_v4() NOT NULL,
    user_in         TEXT,
    user_package_id UUID,
    template_id     UUID,
    contract_id     UUID,
    status          TEXT,
    created_date    TIMESTAMP DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_upu_package_template
    ON "user".user_package_usage (user_package_id, template_id, status);
CREATE INDEX IF NOT EXISTS idx_upu_contract
    ON "user".user_package_usage (contract_id);
